/**
 * Type stub for the CJS FoxSchema bundle generated by scripts/bundle-foxschema.mjs.
 * The .cjs file itself is produced at build time and is not linted by the n8n scanner.
 */
export type FoxRoutineParameter = {
	name: string;
	type: string;
	mode: string;
	ordinal?: number;
};

export type FoxColumnInfo = {
	name: string;
	type: string;
	nullable?: boolean;
	defaultValue?: string;
	primaryKey?: boolean;
	identity?: boolean;
};

export type FoxTableSchema = {
	name: string;
	objectType: string;
	columns: FoxColumnInfo[];
	parameters?: FoxRoutineParameter[];
	functionKind?: string;
	definition?: string;
};

export const ConnectionFactory: {
	create: (
		provider: string,
		options: Record<string, unknown>,
		opts?: { pooled?: boolean },
	) => Promise<unknown>;
	close: (provider: string, connection: unknown) => Promise<void>;
	executeQuery: <T = Record<string, unknown>>(
		provider: string,
		options: Record<string, unknown>,
		sql: string,
		params?: readonly unknown[],
	) => Promise<T[]>;
	closeAll: () => Promise<void>;
};

export function getRegisteredProvider(dialect: string): {
	testConnection: (options: Record<string, unknown>) => Promise<boolean>;
	getTables?: (
		options: Record<string, unknown>,
		schema: string,
	) => Promise<FoxTableSchema[]>;
};

export function getAdapter(dialect: string): {
	query: <T = Record<string, unknown>>(
		connection: unknown,
		sql: string,
		params: readonly unknown[],
	) => Promise<T[]>;
	beginTransaction: (connection: unknown) => Promise<void>;
	commitTransaction: (connection: unknown) => Promise<void>;
	rollbackTransaction: (connection: unknown) => Promise<void>;
	packageName: string;
};
